<template><Card><h2>{{category?'商品类目':'商品单位'}}</h2><StatusPanel :error="error" :pending="pending" :busy="busy" :loading="loading" @recover="recover" @retry="retryOriginal" @abandon="abandonPending"/><div class="s1-toolbar"><Button type="primary" :disabled="pending" @click="edit(null)">新增{{category?'类目':'单位'}}</Button><Button @click="reload">刷新</Button></div><Table :columns="columns" :data="records" :loading="loading" no-data-text="暂无数据"><template slot="enabled" slot-scope="{row}"><Tag :color="row.enabled?'green':'default'">{{row.enabled?'启用':'停用'}}</Tag></template><template slot="action" slot-scope="{row}"><Button size="small" :disabled="pending" @click="edit(row)">编辑</Button><Button size="small" :disabled="pending||busy" @click="toggle(row)">{{row.enabled?'停用':'启用'}}</Button><Button size="small" @click="detail(row)">历史</Button></template></Table><Drawer v-model="show" :title="editing?'编辑':'新增'" width="700" :mask-closable="false"><FieldsForm v-model="form" :fields="fields" :disabled="busy||pending"/><Button type="primary" :loading="busy" :disabled="pending" @click="save">保存</Button></Drawer><Drawer v-model="historyShow" title="配置历史与影响范围" width="80"><RecordDetail v-if="selected" :value="selected"/><Page v-if="selected&&selected.impact" :total="Math.max(selected.impact.storeTotal,selected.impact.goodsTotal)" :current="impactPage" :page-size="20" show-total @on-change="impactPage=$event;detail(selected.item,false)"/></Drawer></Card></template>
<script>import {pageMixin} from './shared';import {s1Read} from '@/api/stage1';import FieldsForm from './FieldsForm';import StatusPanel from './StatusPanel';import RecordDetail from './RecordDetail';export default {props:{category:Boolean},mixins:[pageMixin],components:{FieldsForm,StatusPanel,RecordDetail},data:()=>({show:false,historyShow:false,editing:null,form:{},types:[],impactPage:1}),computed:{path(){return this.category?'/categories':'/units';},columns(){return [{title:'名称',key:'name'},...(this.category?[{title:'层级',key:'level',width:80},{title:'父级编号',key:'parentId',minWidth:170},{title:'排序',key:'sort',width:80}]:[]),{title:'状态',slot:'enabled',width:90},{title:'引用商品数',key:'referencedGoods',width:110},{title:'版本',key:'version',width:80},{title:'操作',slot:'action',width:230}];},fields(){return [{key:'name',label:'名称',required:true,max:this.category?30:10},...(this.category?[{key:'parentId',label:'父级类目',type:'select',options:[{value:'0',label:'顶级类目'},...this.records.filter(r=>r.level<3&&(!this.editing||r.id!==this.editing.id)).map(r=>({value:r.id,label:r.name+' · '+r.id}))]},{key:'sort',label:'排序',type:'integer',max:9999},{key:'qualificationTypes',label:'必需专项资质',type:'multi',options:this.types.filter(t=>t.scope==='CATEGORY'&&t.enabled).map(t=>({value:t.code,label:t.code}))}]:[]),{key:'reason',label:'变更原因',required:true,type:'textarea',max:500}];}},mounted(){this.reload();},methods:{async reload(){await this.load(this.path);if(this.category)try{this.types=await s1Read('/qualification-types');}catch(e){this.error=e.message;}},edit(row){this.editing=row;this.form={name:row?row.name:'',...(this.category?{parentId:row?row.parentId:'0',sort:row?row.sort:0,qualificationTypes:row?[...row.qualificationTypes]:[]}:{}),reason:''};this.show=true;},async save(){try{await this.run(this.path+(this.editing?'/'+this.editing.id:''),{...this.form,...(this.editing?{expectedVersion:this.editing.version}:{})},this.editing?'PUT':'POST');this.show=false;await this.reload();}catch(_){}},async toggle(row){const result=await this.reasonAction(this.path+'/'+row.id+(row.enabled?'/disable':'/enable'),row.enabled?'停用后相关商品将重新校验经营范围':'启用配置',{expectedVersion:row.version});if(result)await this.reload();},async detail(row,reset=true){if(reset)this.impactPage=1;try{this.selected=await s1Read(this.path+'/'+row.id,{pageNumber:this.impactPage,pageSize:20});this.historyShow=true;}catch(e){this.error=e.message;}}}};</script>
<style scoped>.s1-toolbar{display:flex;gap:12px;margin:18px 0}.ivu-btn{margin-right:8px}</style>
